class Solution {
    public int connectSticks(int[] sticks) {
        MinHeap heap = new MinHeap(sticks.length * 2 + 1);
        for (int stick : sticks) {
            heap.push(stick);
        }
        long totalCost = 0;
        while (heap.size() > 1) {
            long merged = heap.poll() + heap.poll();
            totalCost += merged;
            heap.push(merged);
        }
        return (int) totalCost;
    }

    private static class MinHeap {
        private final long[] heap;
        private int size;

        MinHeap(int capacity) {
            heap = new long[Math.max(2, capacity + 1)];
        }

        int size() {
            return size;
        }

        void push(long value) {
            heap[++size] = value;
            siftUp(size);
        }

        long poll() {
            long result = heap[1];
            heap[1] = heap[size--];
            siftDown(1);
            return result;
        }

        private void siftUp(int index) {
            while (index > 1) {
                int parent = index / 2;
                if (heap[parent] <= heap[index]) {
                    break;
                }
                swap(parent, index);
                index = parent;
            }
        }

        private void siftDown(int index) {
            while (index * 2 <= size) {
                int child = index * 2;
                if (child + 1 <= size && heap[child + 1] < heap[child]) {
                    child++;
                }
                if (heap[index] <= heap[child]) {
                    break;
                }
                swap(index, child);
                index = child;
            }
        }

        private void swap(int a, int b) {
            long temp = heap[a];
            heap[a] = heap[b];
            heap[b] = temp;
        }
    }
}

class Solution {
    public int connectSticks(int[] sticks) {
        java.util.TreeMap<Long, Integer> counts = new java.util.TreeMap<>();
        for (int stick : sticks) {
            counts.merge((long) stick, 1, Integer::sum);
        }
        int remaining = sticks.length;
        long totalCost = 0;
        while (remaining > 1) {
            long first = removeSmallest(counts);
            long second = removeSmallest(counts);
            long merged = first + second;
            totalCost += merged;
            counts.merge(merged, 1, Integer::sum);
            remaining--;
        }
        return (int) totalCost;
    }

    private long removeSmallest(java.util.TreeMap<Long, Integer> counts) {
        java.util.Map.Entry<Long, Integer> entry = counts.firstEntry();
        long value = entry.getKey();
        if (entry.getValue() == 1) {
            counts.remove(value);
        } else {
            counts.put(value, entry.getValue() - 1);
        }
        return value;
    }
}

class Solution {
    public int connectSticks(int[] sticks) {
        java.util.Arrays.sort(sticks);
        java.util.ArrayDeque<Long> mergedQueue = new java.util.ArrayDeque<>();
        int[] cursor = new int[] {0};
        long totalCost = 0;
        for (int round = 0; round < sticks.length - 1; round++) {
            long first = takeNext(sticks, cursor, mergedQueue);
            long second = takeNext(sticks, cursor, mergedQueue);
            long merged = first + second;
            totalCost += merged;
            mergedQueue.addLast(merged);
        }
        return (int) totalCost;
    }

    private long takeNext(int[] sticks, int[] cursor, java.util.ArrayDeque<Long> mergedQueue) {
        if (cursor[0] < sticks.length
                && (mergedQueue.isEmpty() || sticks[cursor[0]] <= mergedQueue.peekFirst())) {
            return sticks[cursor[0]++];
        }
        return mergedQueue.removeFirst();
    }
}

class Solution {
    public int connectSticks(int[] sticks) {
        java.util.List<Long> stickList = new java.util.ArrayList<>();
        for (int stick : sticks) {
            stickList.add((long) stick);
        }
        long totalCost = 0;
        while (stickList.size() > 1) {
            java.util.Collections.sort(stickList);
            long merged = stickList.remove(0) + stickList.remove(0);
            totalCost += merged;
            stickList.add(merged);
        }
        return (int) totalCost;
    }
}
